# ----------------------------------------------------------------- node boundary


def _mark_interrupt(update: Mapping[str, Any], node_id: str) -> dict[str, Any]:
    """Record a graceful signal on the guard record so routing stays pure."""

    marked = dict(update)
    guard = marked.get("pending_guard")
    guard = dict(guard) if isinstance(guard, Mapping) else {"node": node_id, "value": None}
    guard["interrupt_requested"] = True
    marked["pending_guard"] = guard
    return marked


_ARTIFACT_ADMISSION_NODES: frozenset[str] = frozenset({
    "D08_VALIDATE_DOMAIN",
    "D09_VALIDATE_CONTENT",
    "D12_VISUAL_BARRIER_AND_JOIN",
    "D20_ADMIT_UNIT_REPAIR",
})


def _persist_admitted_head_updates(
    node_id: str,
    state: Mapping[str, Any],
    update: Mapping[str, Any],
    context: RuntimeContext,
) -> None:
    """Commit every state head update to the replay-safe ArtifactStore first.

    The state reducers prove lineage but do not write the bytes D11/D13 later
    resolve. This boundary bridges those two halves atomically enough for
    checkpoint replay: `admit_version` is idempotent by a deterministic key,
    and an already-equal physical head is an explicit successful replay.
    Failed pre-admission candidates carry no head update and never enter here.
    """

    if node_id not in _ARTIFACT_ADMISSION_NODES:
        return
    head_updates = update.get("artifact_heads")
    if not isinstance(head_updates, Mapping) or not head_updates:
        return
    store = getattr(context, "path_guard", None)
    if not isinstance(store, ArtifactStore):
        raise GraphBindingError("artifact admission requires the runtime ArtifactStore")

    candidates_by_identity: dict[tuple[Any, Any, Any], Mapping[str, Any]] = {}
    for record in (
        list(state.get("artifact_versions") or [])
        + list(update.get("artifact_versions") or [])
    ):
        if not isinstance(record, Mapping):
            continue
        identity = (record.get("stream"), record.get("version"), record.get("hash"))
        prior = candidates_by_identity.get(identity)
        if prior is not None and prior.get("body") != record.get("body"):
            raise GraphBindingError(
                f"artifact identity {identity!r} resolves to conflicting immutable bodies"
            )
        candidates_by_identity[identity] = record
    candidates = list(candidates_by_identity.values())
    for stream_id, head in sorted(head_updates.items()):
        if not isinstance(stream_id, str) or not isinstance(head, Mapping):
            raise GraphBindingError("artifact head update is not a stream/head mapping")
        parts = stream_id.split("/")
        if len(parts) != 3 or parts[0] != UNIT_SCOPE:
            raise GraphBindingError(f"unsupported unit artifact stream {stream_id!r}")
        _scope, unit_id, channel = parts
        matching = [
            record for record in candidates
            if record.get("stream") == stream_id
            and record.get("hash") == head.get("hash")
            and record.get("version") == head.get("version")
        ]
        if len(matching) != 1 or not isinstance(matching[0].get("body"), Mapping):
            raise GraphBindingError(
                f"head {stream_id}@{head.get('version')} has no unique immutable body record")
        body = dict(matching[0]["body"])
        if artifact_digest(body) != head.get("hash"):
            raise GraphBindingError(f"head {stream_id} does not hash its immutable body")
        stream = ArtifactStream(scope=UNIT_SCOPE, unit_id=unit_id, channel=channel)
        idempotency_key = artifact_digest({
            "node_id": node_id,
            "stream": stream_id,
            "version": head.get("version"),
            "hash": head.get("hash"),
        })
        admitted = store.admit_version(
            stream,
            data=canonical_json_bytes(body),
            version=int(head["version"]),
            parent_hash=head.get("parent_hash"),
            idempotency_key=idempotency_key,
        )
        current = store.current_head(stream)
        if current is not None and current.record_hash == admitted.record_hash:
            continue
        store.advance_head(stream, admitted)


def _boundary(node_id: str, body: Callable[..., Any], *, model_node: bool) -> Callable[..., Any]:
    """Wrap one node body in the common boundary of spec section 6.1.

    LangGraph injects `Runtime`, not the opened services, so the boundary is also
    the only place the `RuntimeContext` reaches a node body — N22's and N23's
    callables take it as an explicit argument precisely so they cannot fetch it
    themselves.
    """

    def node(state: Mapping[str, Any], runtime: Runtime[RuntimeContext]) -> dict[str, Any]:
        context = getattr(runtime, "context", None)
        try:
            if model_node:
                update = body(state, build_model_node_context(context))
            else:
                update = body(state, context)
            _persist_admitted_head_updates(node_id, state, update, context)
        except GraphBubbleUp:
            # LangGraph's own control flow (interrupt/resume propagation) is not a
            # product failure and must reach the engine untouched.
            raise
        except Exception as error:  # the classified-failure contract of spec 6.1
            # A terminal_candidate is built here, not left for some later node to
            # supply: `_failure_destination` routes straight to D98_WRITE_TERMINAL
            # the moment `pending_failure` is truthy, with no dynamic-guard hop
            # through a classifier in between (unlike a model node's failure,
            # which D91 gets to classify first). Without one, D98's own
            # independent revalidation (nodes/terminal.py) always rejects a bare
            # `None` candidate as "not a JSON object" -- discarding the real
            # `error` message into an uninformative generic rejection. Shape
            # matches every other SYSTEM_FAILURE writer (model_nodes.py D91,
            # repair.py D17/D18, workbook.py D29) exactly: D98's validator is one
            # shared, independent re-derivation, not a per-writer contract.
            failure_state = state if isinstance(state, Mapping) else {}
            artifact_heads = failure_state.get("artifact_heads") or {}
            return {
                "pending_failure": {
                    "node": node_id,
                    "class": "system",
                    "cause": "unhandled",
                    "message": f"{type(error).__name__}: {error}",
                    "evidence": {"boundary": "node"},
                },
                "pending_guard": None,
                "terminal_candidate": {
                    "kind": "SYSTEM_FAILURE",
                    "failure": {"class": "system", "cause": "unhandled"},
                    "node": node_id,
                    "safe_heads": {
                        stream: head.get("hash")
                        for stream, head in sorted(artifact_heads.items())
                        if isinstance(head, dict)
                    },
                    "audit_high_water_mark": len(failure_state.get("evidence_index_entries") or []),
                },
            }
        token = getattr(context, "signal_token", None)
        if token is not None and bool(getattr(token, "is_set", lambda: False)()):
            return _mark_interrupt(update, node_id)
        return dict(update)

    node.__name__ = node_id
    node.__qualname__ = node_id
    node.__doc__ = getattr(body, "__doc__", None)
    node.plan26_binding = _binding_record(node_id, body)  # type: ignore[attr-defined]
    return node


def _underlying(body: Callable[..., Any]) -> Callable[..., Any]:
    """The authored function behind a decorated node, for identity and audit."""

    return getattr(body, "node_body", body)
class ArtifactStore:
    def __init__(self, root: Path) -> None:
        root = Path(root)
        root.mkdir(parents=True, exist_ok=True)
        self._root = root.resolve(strict=True)

    @property
    def root(self) -> Path:
        return self._root

    def resolve(self, relative: str) -> Path:
        return resolve_within(self._root, relative)

    def _assert_admissible(self, relative: str, target: Path) -> None:
        parts = PurePosixPath(relative).parts
        if ACCEPTED_SEGMENT in parts:
            index = parts.index(ACCEPTED_SEGMENT)
            receipt_parts = parts[: index + 2]
            if len(receipt_parts) == index + 2:
                receipt_dir = self._root.joinpath(*receipt_parts)
                if receipt_dir.exists():
                    raise AcceptedImmutable(
                        f"accepted receipt {'/'.join(receipt_parts)} is sealed; refusing to write {relative}"
                    )
        if target.exists():
            raise ArtifactConflict(f"refusing to overwrite existing artifact: {relative}")

    def stage(self, data: bytes) -> Path:
        """Write ``data`` to a staging file that is not yet visible at any final path."""
        staging = self._root / STAGING_DIRNAME
        staging.mkdir(parents=True, exist_ok=True)
        handle, name = tempfile.mkstemp(dir=staging, prefix="stage-", suffix=".part")
        with os.fdopen(handle, "wb") as fh:
            fh.write(data)
            fh.flush()
            os.fsync(fh.fileno())
        return Path(name)

    def commit(self, staged: Path, relative: str, *, overwrite: bool = False) -> Path:
        staged = Path(staged)
        if staged.parent.resolve() != (self._root / STAGING_DIRNAME).resolve():
            raise ArtifactError(f"staged file is not in the store staging area: {staged}")
        target = self.resolve(relative)
        if not overwrite:
            self._assert_admissible(relative, target)
        elif ACCEPTED_SEGMENT in PurePosixPath(relative).parts:
            raise AcceptedImmutable(f"accepted bytes are never overwritten: {relative}")
        target.parent.mkdir(parents=True, exist_ok=True)
        os.replace(staged, target)
        self._fsync_dir(target.parent)
        return target

    def put_bytes(self, relative: str, data: bytes, *, overwrite: bool = False) -> Path:
        target = self.resolve(relative)
        if not overwrite:
            self._assert_admissible(relative, target)
        elif ACCEPTED_SEGMENT in PurePosixPath(relative).parts:
            raise AcceptedImmutable(f"accepted bytes are never overwritten: {relative}")
        staged = self.stage(data)
        try:
            return self.commit(staged, relative, overwrite=overwrite)
        except BaseException:
            staged.unlink(missing_ok=True)
            raise

    @staticmethod
    def _fsync_dir(directory: Path) -> None:
        handle = os.open(directory, os.O_RDONLY)
        try:
            os.fsync(handle)
        finally:
            os.close(handle)

    def recover_staging(self) -> list[dict[str, Any]]:
        """Quarantine orphaned staged bytes left by a crash before rename."""
        staging = self._root / STAGING_DIRNAME
        if not staging.is_dir():
            return []
        quarantine = self._root / QUARANTINE_DIRNAME
        recovered: list[dict[str, Any]] = []
        for orphan in sorted(staging.iterdir()):
            if not orphan.is_file() or orphan.is_symlink():
                continue
            data = orphan.read_bytes()
            digest = bytes_digest(data)
            quarantine.mkdir(parents=True, exist_ok=True)
            destination = quarantine / f"{digest}-{orphan.name}"
            os.replace(orphan, destination)
            recovered.append(
                {
                    "staged_name": orphan.name,
                    "quarantine_path": str(destination.relative_to(self._root)),
                    "content_hash": digest,
                    "byte_size": len(data),
                }
            )
        if recovered:
            self._fsync_dir(quarantine)
        return recovered

    def read_version(self, stream: ArtifactStream, version: int) -> VersionRecord | None:
        path = self.resolve(stream.record_path(version))
        if not path.is_file():
            return None
        stored = json.loads(path.read_text(encoding="utf-8"))
        record = _record_from_body(stored["record"])
        if record.record_hash != stored["record_hash"]:
            raise IntegrityError(f"version record hash mismatch at {stream.record_path(version)}")
        return record

    def latest_version(self, stream: ArtifactStream) -> VersionRecord | None:
        records_dir = self.resolve(f"{stream.versions_dir}/records")
        if not records_dir.is_dir():
            return None
        versions = sorted(int(p.stem) for p in records_dir.glob("*.json"))
        if not versions:
            return None
        return self.read_version(stream, versions[-1])

    def admit_version(
        self,
        stream: ArtifactStream,
        *,
        data: bytes,
        version: int,
        parent_hash: str | None,
        idempotency_key: str,
    ) -> VersionRecord:
        """Admit immutable artifact bytes as ``version`` of ``stream``."""
        if not isinstance(data, (bytes, bytearray)):
            raise ArtifactError("artifact data must be raw bytes")
        data = bytes(data)
        version = int(version)
        if version < 1:
            raise ArtifactError(f"version must be >= 1, got {version}")
        _require_token(idempotency_key, "idempotency_key")
        if parent_hash is not None:
            _require_hash(parent_hash, "parent_hash")

        content_hash = bytes_digest(data)
        body = {
            "schema": VERSION_RECORD_SCHEMA,
            "stream_id": stream.stream_id,
            "scope": stream.scope,
            "unit_id": stream.unit_id,
            "channel": stream.channel,
            "version": version,
            "parent_hash": parent_hash,
            "content_hash": content_hash,
            "byte_size": len(data),
            "artifact_path": stream.blob_path(content_hash),
            "idempotency_key": idempotency_key,
        }
        record = _record_from_body(body)

        key_relative = stream.key_path(idempotency_key)
        key_path = self.resolve(key_relative)
        if key_path.is_file():
            claimed = json.loads(key_path.read_text(encoding="utf-8"))
            existing = self.read_version(stream, claimed["version"])
            if existing is None:
                raise IntegrityError(f"idempotency key {idempotency_key!r} points at a missing version record")
            if existing.record_hash != record.record_hash:
                raise ArtifactConflict(
                    f"idempotency key {idempotency_key!r} already admitted a different artifact "
                    f"({existing.content_hash} != {content_hash})"
                )
            return existing

        existing_version = self.read_version(stream, version)
        if existing_version is not None:
            raise ArtifactConflict(
                f"version {version} of {stream.stream_id} already exists "
                f"({existing_version.content_hash})"
            )

        predecessor = self.read_version(stream, version - 1) if version > 1 else None
        if version == 1:
            if parent_hash is not None:
                raise ArtifactConflict("version 1 must declare parent_hash=None")
        else:
            if predecessor is None:
                raise ArtifactConflict(
                    f"version {version} of {stream.stream_id} has no admitted parent version {version - 1}"
                )
            if parent_hash != predecessor.content_hash:
                raise ArtifactConflict(
                    f"declared parent {parent_hash} does not match version {version - 1} "
                    f"content hash {predecessor.content_hash}"
                )

        blob_relative = stream.blob_path(content_hash)
        blob_path = self.resolve(blob_relative)
        if blob_path.is_file():
            if file_digest(blob_path) != content_hash:
                raise IntegrityError(f"content-addressed blob is corrupt: {blob_relative}")
        else:
            self.put_bytes(blob_relative, data)

        self.put_bytes(
            stream.record_path(version),
            canonical_json_bytes({"record": body, "record_hash": record.record_hash}),
        )
        self.put_bytes(
            key_relative,
            canonical_json_bytes(
                {
                    "idempotency_key": idempotency_key,
                    "stream_id": stream.stream_id,
                    "version": version,
                    "content_hash": content_hash,
                    "record_hash": record.record_hash,
                }
            ),
        )
        return record

    def current_head(self, stream: ArtifactStream) -> VersionRecord | None:
        path = self.resolve(stream.head_path)
        if not path.is_file():
            return None
        stored = json.loads(path.read_text(encoding="utf-8"))
        record = _record_from_body(stored["record"])
        if record.record_hash != stored["record_hash"]:
            raise IntegrityError(f"head record hash mismatch at {stream.head_path}")
        return record

    def advance_head(self, stream: ArtifactStream, record: VersionRecord) -> VersionRecord:
        """Advance the head pointer to a child of the current head only."""
        if record.stream_id != stream.stream_id:
            raise HeadAdvanceError(
                f"record belongs to {record.stream_id}, not {stream.stream_id}"
            )
        admitted = self.read_version(stream, record.version)
        if admitted is None or admitted.record_hash != record.record_hash:
            raise HeadAdvanceError(
                f"version {record.version} of {stream.stream_id} is not an admitted artifact"
            )
        current = self.current_head(stream)
        if current is None:
            if record.version != 1 or record.parent_hash is not None:
                raise HeadAdvanceError(
                    "first head must be version 1 with parent_hash=None, "
                    f"got version {record.version} parent {record.parent_hash}"
                )
        else:
            if record.version != current.version + 1:
                raise HeadAdvanceError(
                    f"head advances one version at a time: current {current.version}, "
                    f"proposed {record.version}"
                )
            if record.parent_hash != current.content_hash:
                raise HeadAdvanceError(
                    f"declared parent {record.parent_hash} is not the current head "
                    f"{current.content_hash}"
                )
        self.put_bytes(
            stream.head_path,
            canonical_json_bytes({"record": record.body(), "record_hash": record.record_hash}),
            overwrite=True,
        )
        return record

    def accept(
        self,
        stream: ArtifactStream,
        *,
        receipt_hash: str,
        files: Mapping[str, bytes],
    ) -> dict[str, str]:
        """Copy bytes into a write-protected ``accepted/<receipt_hash>/`` directory."""
        _require_hash(receipt_hash, "receipt_hash")

def project(node_id: str, state: Mapping[str, Any]) -> dict[str, Any]:
    """Build the narrow authorized projection of ``state`` for ``node_id``.

    Fields absent from ``state`` take their channel's empty value, so a node
    body never distinguishes "never written" from "written empty" and never
    branches on a key it was not authorized to see.
    """

    spec = NODE_CATALOGUE[node_id]
    projection: dict[str, Any] = {}
    for field in spec.inputs:
        value = state.get(field)
        projection[field] = channel_default(field) if value is None else value
    return projection


def failure_record(
    node_id: str,
    error: ExpectedFailure,
    *,
    at: str | None = None,
) -> dict[str, Any]:
    """Normalize a classified failure into the one `pending_failure` shape."""

    failure_class = error.failure_class
    permitted = CAUSES_BY_CLASS[failure_class]
    if error.cause not in permitted:
        raise CatalogueViolation(
            f"{node_id}: cause {error.cause!r} is not declared for class {failure_class!r}"
        )
    record: dict[str, Any] = {
        "node": node_id,
        "class": failure_class,
        "cause": error.cause,
        "message": str(error),
        "evidence": error.evidence,
    }
    if at is not None:
        record["at"] = at
    return record


def guard(node_id: str, value: str, **detail: Any) -> dict[str, Any]:
    """Build the `pending_guard` record a routing function reads.

    The node states its deterministic classification; `routing.py` (N20) decides
    the destination. Keeping those separate is why a node body can never name an
    edge.
    """

    spec = NODE_CATALOGUE[node_id]
    if value not in spec.guards:
        raise CatalogueViolation(f"{node_id}: undeclared guard value {value!r}")
    return {"node": node_id, "value": value, "detail": detail}


def require(condition: bool, cause: str, message: str, **evidence: Any) -> None:
    """Fail closed with a typed system failure when ``condition`` does not hold."""

    if not condition:
        raise SystemFailure(cause, message, evidence)


def deterministic_node(node_id: str) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    """Bind a bounded callable to its frozen catalogue row.

    The wrapper narrows state to the authorized projection, rejects any update
    naming an unauthorized channel, and converts a classified
    :class:`ExpectedFailure` into `pending_failure`. Every other exception is
    re-raised untouched.
    """

    spec = NODE_CATALOGUE[node_id]
    authorized = frozenset(spec.outputs) | frozenset(COMMON_OUTPUT_CHANNELS)

    def decorate(body: Callable[..., Any]) -> Callable[..., Any]:
        def node(state: Mapping[str, Any], runtime_context: Any = None) -> dict[str, Any]:
            projection = project(node_id, state)
            try:
                update = body(projection, runtime_context)
            except ExpectedFailure as error:
                # Spec 6.1: every outgoing guard reads `pending_failure` first, so a
                # classified failure clears any stale routing classification.
                #
                # A terminal_candidate is built here too, not left for some later
                # node to supply: `_failure_destination` (routing.py) routes
                # straight to D98_WRITE_TERMINAL the moment `pending_failure` is
                # truthy, with no classifier hop in between for a deterministic
                # node's failure (unlike a model node's, which D91 gets to shape
                # first). Without one, D98's own independent revalidation always
                # rejected a bare `None` candidate as "not a JSON object" --
                # discarding the real, already-classified failure into an
                # uninformative generic rejection. The same gap, and the same fix,
                # as graph.py's `_boundary` (N40V7-F12): shape matches every other
                # SYSTEM_FAILURE writer exactly. `state` here is the full incoming
                # state, before `project()` narrows it to this node's own
                # projection, so `artifact_heads`/`evidence_index_entries` are
                # still reachable.
                full_state = state if isinstance(state, Mapping) else {}
                artifact_heads = full_state.get("artifact_heads") or {}
                return {
                    "pending_failure": failure_record(node_id, error),
                    "pending_guard": None,
                    "terminal_candidate": {
                        "kind": "SYSTEM_FAILURE",
                        "failure": {"class": error.failure_class, "cause": error.cause},
                        "node": node_id,
                        "safe_heads": {
                            stream: head.get("hash")
                            for stream, head in sorted(artifact_heads.items())
                            if isinstance(head, dict)
                        },
                        "audit_high_water_mark": len(full_state.get("evidence_index_entries") or []),
                    },
                }
            if not isinstance(update, dict):
                raise CatalogueViolation(
                    f"{node_id}: node body returned {type(update).__name__}, expected a dict update"
                )
            unauthorized = sorted(set(update) - authorized)
            if unauthorized:
                raise CatalogueViolation(
                    f"{node_id}: update writes unauthorized channels {unauthorized}"
                )
            return update

        node.__name__ = node_id
        node.__qualname__ = node_id
        node.__doc__ = body.__doc__
        node.node_id = node_id  # type: ignore[attr-defined]
        node.node_spec = spec  # type: ignore[attr-defined]
        node.node_body = body  # type: ignore[attr-defined]
        return node

    return decorate


def stream_id(unit_id: str, channel: str) -> str:
    """The one artifact-stream identifier convention for head and version keys."""

    return f"units/{unit_id}/{channel}"


